x=range(len(c));axs[2].bar([i-.2 for i in x],[q['retained_chunks_after_merge'] for q in c],.4,label='Retained chunks');axs[2].bar([i+.2 for i in x],[q['embedding_segments_prepared'] for q in c],.4,label='Embedding segments');axs[2].set_title('Retained chunks vs embedding segments');axs[2].set_ylabel('Count');axs[2].set_xticks(x);axs[2].set_xticklabels(labs,rotation=50,ha='right',fontsize=8);axs[2].legend();axs[2].grid(axis='y',alpha=.2)
